function TimelineController:__init()
    self.controller = nil
    self.isInit = false

    self.m_hasPlayed = false

    -- 回调函数:
    self.OnTimelineStop = nil -- Action
end


function TimelineController:__delete()
end




function TimelineController:Start()
    KTool.SetActive(self.controller.gameObject, true)

    assert( self.playableDirector )


    assert( isNotNull( URPCameraController.Instance ) and isNotNull(  URPCameraController.Instance.mainCamera ) )
    local cBrain = KTool.GetComponent(URPCameraController.Instance.mainCamera.gameObject, typeof(CinemachineBrain))
    assert(cBrain)



    local timelineAsset = self.playableDirector.playableAsset
    ----

    local list = support.new_list(typeof(CS.UnityEngine.Timeline.TrackAsset))
    list:AddRange(timelineAsset:GetOutputTracks())

    for i = 0, list.Count - 1 do
        local track = list[i]
        if track.name == "targetCamera" then
            self.playableDirector:SetGenericBinding(track, cBrain)
        end
    end

    self.playableDirector:stopped( '+', function(playableDirector_)
        self:WhenTimelineStop()
    end)
    ---
    DreamSpaceLuaUtils.StopCoroutine( self.co_0 )
    self.co_0 = cs_coroutine.start(self.DelayInit, self)
end




function TimelineController:DelayInit() 

    if isNotNull(self.vcamCopy) then 

        -- 只会查找 N 次;
        for i = 0, DreamSpaceStates.DelayInitWaitFrames do
            self.vcam3rdPersonFollow = GlobalsInDreamSpace.FindComponent("vcam3rdPersonFollow") -- CinemachineVirtualCamera
            if isNotNull(self.vcam3rdPersonFollow) then
                break
            end
            coroutine.yield(Yielders.EndOfFrame)
        end
        if isNull(self.vcam3rdPersonFollow) then
            printError("始终没能找到 vcam3rdPersonFollow, 请查找原因")
            return
        end

        ---@type Cinemachine.Cinemachine3rdPersonFollow
        self.vcamCopy_3rdPersonFollow = DreamSpaceLuaUtils.GetCinemachineComponent( self.vcamCopy, typeof(Cinemachine3rdPersonFollow) )
        assert(self.vcamCopy_3rdPersonFollow)

        ---@type Cinemachine.Cinemachine3rdPersonFollow
        self.vcamRole_3rdPersonFollow = DreamSpaceLuaUtils.GetCinemachineComponent( self.vcam3rdPersonFollow, typeof(Cinemachine3rdPersonFollow) )
        assert(self.vcamRole_3rdPersonFollow)
    end

    self.isInit = true
end



function TimelineController:OnDestroy()
    DreamSpaceLuaUtils.StopCoroutine( self.co_0 )
    DreamSpaceLuaUtils.StopCoroutine( self.co_1 )
    self.co_0 = nil
    self.co_1 = nil
    ---
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end

-- =========================================== Self ================================================ --




-- 外部调用本函数来启动播放 timeline
function TimelineController:BeginPlay()

    DreamSpaceLuaUtils.StopCoroutine( self.co_1 )
    self.co_1 = cs_coroutine.start(function()

        while self.isInit ~= true do
            printError("koko - TimelineController DelayInit() 尚未结束")
            coroutine.yield(Yielders.EndOfFrame)
        end

        -- vcamCopy 存在的目的就是用它来 模拟一个 vcam3rdPersonFollow:
        if isNotNull(self.vcamCopy) then 
            DreamSpaceLuaUtils.CopyCinemachine3rdPersonFollow( self.vcam3rdPersonFollow, self.vcamCopy, self.vcamRole_3rdPersonFollow, self.vcamCopy_3rdPersonFollow )
        end
        
        --- 有些 timeline 触发得较早, 此时场景其它资源尚未准备妥当 
        while self.isInit == false do
            coroutine.yield(Yielders.EndOfFrame)
        end
        ---
        if self.m_hasPlayed == false then
            self.m_hasPlayed = true
            DreamSpaceStates.LockInput_ByCount( DreamSpaceStates.InputLockState.Lock ) -- 希望禁止玩家输入
            DreamSpaceStates.LockSubPanelFreeInPC_ByCount( DreamSpaceStates.InputLockState.Lock ) -- PC 版 禁止打开 ui 子界面 
            
            coroutine.yield(Yielders.EndOfFrame)
            print("进入timeline")
            self.playableDirector:Play()
        end
    end)
end






function TimelineController:WhenTimelineStop()

    DreamSpaceStates.LockInput_ByCount(     DreamSpaceStates.InputLockState.Unlock ) -- 解除禁止:玩家输入
    DreamSpaceStates.LockViewRotate_ByFlag( DreamSpaceStates.InputLockState.Unlock ) -- 解除禁止:玩家旋转视角
    DreamSpaceStates.LockSubPanelFreeInPC_ByCount( DreamSpaceStates.InputLockState.Unlock ) -- PC 版 允许打开 ui 子界面 

    if self.OnTimelineStop ~= nil then
        self.OnTimelineStop()
    end

end





return TimelineController
